/* Figma implementation. Demo records stay in this browser and are shared by both app views. */
'use strict';
const STORE='cedar-valley-connected-demo-v1';
const defaults={group:'Horizon Foundation Annual Leadership Retreat',start:'2026-11-12',end:'2026-11-15',type:'Leadership retreat',single:12,double:10,budget:150,organization:'Horizon Foundation',guests:32,first:'Maya',last:'Thompson',email:'maya.thompson@horizon.example',special:'Meeting hall for 3 days and group meals.',address:'480 Alder Street, Portland, Oregon 97205'};
const initial=()=>({version:1,request:null,quote:null,reservation:null,events:[],ui:{app:'guest',guest:'form',admin:'list',guide:false,recording:false},draft:{}});
let state;try{state=JSON.parse(localStorage.getItem(STORE))||initial();if(state.version!==1)state=initial();}catch{state=initial();}
let modal=null,wizard=null,resWizard=null,signatureMode='type',drawn=false,drawData=null,lastFocus=null;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n)||0);
const img=(file,alt='',cls='')=>`<img src="./${file}" alt="${esc(alt)}" ${cls?`class="${cls}"`:''}>`;
const button=(text,action,cls='',disabled=false)=>`<button type="button" class="btn ${cls}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;
const badge=s=>`<span class="badge ${['Pending','Sent','Pending Approval'].includes(s)?'warning':['Confirmed','Available','Paid','Matches request'].includes(s)?'success':''}">${esc(s)}</span>`;
const field=(label,name,value,type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${type==='text'||type==='email'||type==='number'?`placeholder="${esc(({group:'Enter retreat or group name',rooms:'e.g. 22 · 12 single, 10 double',budget:'e.g. 150',organization:'Organization name',guests:'Number of guests',first:'First name',last:'Last name',email:'you@organization.com'})[name]||'')}"`:""} ${extra}></label>`;
const select=(label,name,value,options,extra='')=>`<label class="field"><span>${label}</span><select name="${name}" ${extra}>${value?'':'<option value="" disabled selected>Select group type</option>'}${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
const textarea=(label,name,value,extra='')=>`<label class="field">${label}<textarea name="${name}" ${extra} placeholder="${name==='special'?'Meeting space, meals, accessibility or other requests…':''}">${esc(value)}</textarea></label>`;
const check=(text,name,checked=false,extra='')=>`<label class="check"><input type="checkbox" name="${name}" ${checked?'checked':''} ${extra}>${text}</label>`;
const panel=(title,body,actions='',cls='')=>`<section class="panel ${cls}"><div class="panel-head"><h2>${title}</h2>${actions}</div><div class="panel-body">${body}</div></section>`;
const detail=(label,value)=>`<div class="detail"><label>${label}</label><strong>${value}</strong></div>`;
const line=(label,value,cls='')=>`<div class="summary-line ${cls}"><span>${label}</span><span>${value}</span></div>`;
function table(headers,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('Browser storage is unavailable. Keep this page open to preserve the demo.',true);}}
function toast(text,error=false){$('#toast').className='toast'+(error?' error-toast':'');$('#toast').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{$('#toast').className='';$('#toast').textContent='';},4500);}
function stage(){return state.reservation?.status==='Confirmed'?6:state.reservation?5:state.quote?.paid?4:state.quote?.signature?3:state.quote?2:state.request?1:0;}
function demoBar(){const names=['Guest request','Admin quote','Guest review','Sign & deposit','Admin conversion','Reservation'];let s=stage();return `<div class="demo-bar ${state.ui.recording?'compact':''}"><div class="demo-brand">CEDAR VALLEY <small>Connected booking demo · Sep 22, 2026</small></div><div class="switcher" role="group" aria-label="Switch demo app"><button data-action="switch-guest" class="${state.ui.app==='guest'?'active':''}" aria-pressed="${state.ui.app==='guest'}">Guest App${state.quote&&state.ui.guest==='received'?' · 1 new quote':''}</button><button data-action="switch-admin" class="${state.ui.app==='admin'?'active':''}" aria-pressed="${state.ui.app==='admin'}">Admin App${state.request&&state.request.status==='Pending'?' · 1 new':''}</button></div><div class="demo-tools"><button data-action="guide" class="hide-recording">${state.ui.guide?'Hide':'Demo'} flow</button><button data-action="recording">${state.ui.recording?'Show controls':'Recording mode'}</button><button data-action="reset" title="Reset the complete demo">Reset demo</button></div></div>${state.ui.recording?'':`<div class="demo-progress"><div class="steps">${names.map((x,i)=>`<span class="${i<s?'done':i===s?'current':'pending'}">${i<s?'✓':i+1} ${x}</span>`).join('<span class="pending">→</span>')}</div><span>GBR-008 · ${s===6?'Complete':'Connected data'}</span></div>`}${state.ui.guide?`<div class="flow-guide"><ol><li><b>Guest:</b> Fill out and submit the group request.</li><li><b>Admin:</b> Open GBR-008, check availability and confirm.</li><li><b>Admin:</b> Convert to group block, select rooms, then send quote.</li><li><b>Guest:</b> Open quote, review BEO and contract, sign and pay demo deposit.</li><li><b>Admin:</b> Review signed booking and convert to reservation.</li><li><b>Admin:</b> Confirm reservation. Switch to Guest to see the final booking.</li></ol></div>`:''}`;}
function sfNav(){return `${img('49e69.png','Salesforce global header','sf-header')}<nav class="sf-nav" aria-label="Admin navigation"><div class="sf-brand">${img('3f889.svg')}Booking Ninjas</div>${['Reservations','Contacts','Properties','Rate Controller','Availability','BN Invoices','Request Manager','Control Panel'].map(x=>`<button data-action="nav-${x.replaceAll(' ','-')}" class="${(x==='Reservations'&&!['availability','invoice','contacts'].includes(state.ui.admin))||(x==='Availability'&&state.ui.admin==='availability')||(x==='BN Invoices'&&state.ui.admin==='invoice')||(x==='Contacts'&&state.ui.admin==='contacts')?'active':''}">${x}</button>`).join('')}</nav>`;}
function adminHeader(kicker,title,sub='',actions='',status=''){const icon=kicker.startsWith('Group Block')?kicker==='Group Block Requests'?`<span class="list-icon">${img('e0b0a.svg')}</span>`:img('e0b0a.svg','','icon'):'';return `<header class="admin-header"><div class="admin-title">${icon}<div>${kicker==='Group Block Request'?breadcrumbs([['Group Block Requests','request-list'],['GBR-008']]):''}${kicker==='Group Block Request'?'':`<small>${kicker}</small>`}<h1>${esc(title)}</h1>${sub?`<div class="sub">${sub}</div>`:''}</div></div><div class="row">${status?`<small>Request status</small>${badge(status)}`:''}${actions}</div></header>`;}
function guestHeader(){return `<header class="guest-header">${img('0d92a.svg','Booking Ninjas')}${state.quote?button('My booking','my-booking','link'):''}</header>`;}
const guestFooter=()=>`<footer class="guest-footer">© 2026 Cedar Valley Retreat & Conference Center. Powered by Booking Ninjas.</footer>`;
function guestForm(){const d=state.request||{group:'',start:'',end:'',type:'',single:0,double:0,budget:'',organization:'',guests:'',first:'',last:'',email:'',special:'',...state.draft};const titles=['Leadership & Team Retreats','Wellness & Yoga Retreats','Spiritual & Faith Retreats','Education Programs'];const descriptions=['Meeting space, rooms and group meals in one stay.','Quiet stays with space for classes and sessions.','Group lodging for your community.','Cohorts, workshops and lodging.'];return `<div class="guest">${guestHeader()}<section class="landing-hero">${img('6d165.png','Cedar Valley retreat venue','hero-img')}<div class="hero-overlay"></div><div class="hero-copy"><div class="eyebrow">CEDAR VALLEY RETREAT & CONFERENCE CENTER</div><h1>Plan your next<br>group retreat</h1><p>One quote for rooms, meeting space and group meals.</p><div class="highlights">${[['e41d2.svg','Rooms, meals &<br>meeting space'],['84b48.svg','Quick<br>response'],['3645a.svg','Planning help<br>from our team']].map(([a,t])=>`<div class="highlight">${img(a)}<span>${t}</span></div>`).join('')}</div></div><div class="hero-note">Great retreats<br>bring people together.</div><form id="request-form" class="quote-form"><h2>Request a Group Quote</h2>${field('Retreat / Group Name','group',d.group,'text','required maxlength="120"')}<div class="grid2">${field('Start Date <span class="required">*</span>','start',d.start,'date','required')}${field('End Date <span class="required">*</span>','end',d.end,'date','required')}</div>${select('Group Type <span class="required">*</span>','type',d.type,['Leadership retreat','Corporate offsite','Wellness retreat','Yoga retreat','Family reunion','Education program'])}<div class="grid2">${field('Rooms Qty <span class="required">*</span>','rooms',d.rooms??(d.single+d.double?`${d.single+d.double} · ${d.single} single, ${d.double} double`:''),'text','required title="Use 22 · 12 single, 10 double or enter a room count"')}${field('Ideal nightly budget','budget',d.budget,'number','min="1" max="2000"')}</div><div class="grid2">${field('Organization','organization',d.organization,'text','required')}${field('Number of guests','guests',d.guests,'number','required min="1" max="60"')}</div><div class="grid2">${field('First Name <span class="required">*</span>','first',d.first,'text','required')}${field('Last Name <span class="required">*</span>','last',d.last,'text','required')}</div>${field('Where should we send quotes? <span class="required">*</span>','email',d.email,'email','required')}${textarea('Any additional requests?','special',d.special)}<div id="request-error" class="error" hidden></div><button class="btn primary" type="submit">Submit Request</button></form></section><section class="occasions"><div class="eyebrow">BUILT FOR EVERY KIND OF RETREAT</div><h2>Group rates for any kind of retreat</h2><div class="occasion-grid">${['94e4b.png','e422a.png','6e441.png','7936e.png'].map((a,i)=>`<article class="occasion">${img(a,titles[i])}<div><h3>${titles[i]}</h3><p>${descriptions[i]}</p></div></article>`).join('')}</div></section><section class="benefits">${[['53222.svg','Group rates','A special rate for your whole group, locked in with your quote.'],['784f6.svg','Dedicated support','Our team helps from your first request to arrival.'],['6b243.svg','One simple quote','Rooms, meeting space and meals together in one place.'],['2d744.svg','Easy for your guests','Each guest books their own room from your group link.']].map(([a,t,p])=>`<div class="benefit">${img(a)}<div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</section><section class="testimonial">${img('c7c30.png','Group dinner at the retreat center')}<div><span style="font-size:40px;color:#b89b6f">“</span><blockquote>“Our leadership retreat came together in one quote, and our guests booked their own rooms in minutes.”</blockquote><small>— Retreat organizer (illustrative)</small><div class="mt">${img('da848.svg')}</div></div></section><footer class="landing-footer"><div class="divider">${img('f8ccf.svg')}</div><div class="row"><span>© 2026 Booking Ninjas. All rights reserved.</span><span>Privacy Policy &nbsp;&nbsp;&nbsp; Terms of Service</span></div></footer></div>`;}
const seedRows=[['GBR-009','Marcus Webb','Brightmoor Leadership Offsite','Corporate offsite','Dec 03 – Dec 06, 2026',18,'$140 – $190','Pending'],['GBR-010','Elena Park','Riverstone Wellness Weekend','Wellness retreat','Dec 10 – Dec 13, 2026',14,'$140 – $210','Confirmed'],['GBR-011','Grace Liu','Calderwood Yoga Retreat','Yoga retreat','Jan 14 – Jan 17, 2027',16,'$140 – $190','Converted'],['GBR-012','Omar Haddad','Summit Family Reunion','Family reunion','Feb 11 – Feb 14, 2027',22,'$140 – $190','Converted'],['GBR-013','Chloe Martin','Pinecrest Faculty Retreat','Education program','Mar 04 – Mar 07, 2027',12,'$140 – $190','Confirmed']];
function dateLabel(s){return new Date(s+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'2-digit',year:'numeric',timeZone:'UTC'});}
function dates(r=state.request||defaults){return `${dateLabel(r.start).replace(/, \d{4}/,'')} – ${dateLabel(r.end)}`;}
function nights(r=state.request||defaults){return Math.round((Date.parse(r.end)-Date.parse(r.start))/86400000);}
function name(r=state.request||defaults){return `${r.first} ${r.last}`;}
function adminList(){const r=state.request;const rows=r?[['GBR-008',name(r),r.group,r.type,dates(r),r.single+r.double,'$140 – $190',r.status],...seedRows]:seedRows;return `<div class="admin">${sfNav()}${adminHeader('Group Block Requests','All requests','',button('New','new-request'))}<div class="list-meta">${rows.length} items · Sorted by Start Date · Updated a few seconds ago</div><div class="admin-main"><section class="panel list-table"><div class="list-toolbar">${field('Search','list-search','','search','placeholder="Search this list..."')}</div><div class="table-wrap"><table id="request-list"><thead><tr>${['REQUEST','CONTACT','GROUP NAME','GROUP TYPE','DATES','ROOMS','RATE RANGE','STATUS','NEXT STEP'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr ${row[0]==='GBR-008'?'class="new-row"':''} data-search="${esc(row.join(' ').toLowerCase())}"><td>${button(row[0],row[0]==='GBR-008'?'open-request':`seed-${row[0]}`,'link')}</td>${row.slice(1,7).map(x=>`<td>${esc(x)}</td>`).join('')}<td>${badge(row[7])}</td><td>${button(row[7]==='Pending'?'Review':row[7]==='Confirmed'?'Convert':'View',row[0]==='GBR-008'?'open-request':`seed-${row[0]}`,'link')}</td></tr>`).join('')}</tbody></table></div></section></div></div>`;}
function totals(q=state.quote||wizard){if(!q)return {rooms:0,space:0,addons:0,subtotal:0,tax:0,total:0,deposit:0};const rooms=q.rooms.reduce((sum,r)=>sum+r.qty*r.rate*nights(),0);const space=q.spaceDays*q.spaceRate;const addons=q.cateringQty*q.cateringRate;const subtotal=rooms+space+addons;const tax=q.tax?Math.round(subtotal*10)/100:0;const total=Math.round((subtotal+tax)*100)/100;return {rooms,space,addons,subtotal,tax,total,deposit:Math.round(total*50)/100};}
function dueDate(){const d=new Date((state.request||defaults).start+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-7);return dateLabel(d.toISOString().slice(0,10));}
function spaceDates(q=state.quote||wizard){const d=new Date((state.request||defaults).start+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+q.spaceDays-1);return `${dateLabel(state.request.start).replace(/, \d{4}/,'')} – ${dateLabel(d.toISOString().slice(0,10))}`;}
function buildQuote(){const r=state.request;return {step:1,code:'GBR-008',status:'Pending',rooms:[{type:'Standard Single Room',bed:'Single',qty:0,rate:140,available:12},{type:'Standard Double Room',bed:'Double',qty:0,rate:140,available:7},{type:'Cabin',bed:'Double',qty:0,rate:190,available:4}],space:'Meeting Hall',layout:'Classroom',spaceDays:nights(),spaceRate:600,spaceTime:'9:00 AM – 5:00 PM',guests:r.guests,cateringQty:0,cateringRate:55,tax:true,billedTo:name(),email:r.email,sendEmail:true,signature:null,paid:false,venueConfirmed:false,notes:[]};}
function addEvent(text,actor){state.events.push({text,actor,date:'Sep 22, 2026'});}
function submitRequest(form){const vals=Object.fromEntries(new FormData(form));const roomNumbers=vals.rooms.match(/\d+/g)?.map(Number)||[];const total=roomNumbers[0];const single=roomNumbers.length>=3?roomNumbers[1]:Math.min(total,12);const double=roomNumbers.length>=3?roomNumbers[2]:total-single;const r={...defaults,...vals,single,double,guests:Number(vals.guests),budget:Number(vals.budget),status:'Pending',id:'GBR-008'};if(!r.group.trim()||!r.first.trim()||!r.last.trim()||!r.organization.trim())throw Error('Please complete the group and organizer details.');if(nights(r)<=0||nights(r)>14)throw Error('End date must be after start date, with a stay of 1–14 nights.');if(!Number.isInteger(total)||total<1||total>23||single<0||double<0||single+double!==total||single>12||double>11)throw Error('Enter a valid room split: up to 12 single and 11 double rooms. Example: 22 · 12 single, 10 double.');if(r.guests>60||r.guests<1)throw Error('The meeting hall supports 1–60 guests.');if(state.quote)throw Error('This request already has a quote. Reset the demo to start a new story.');state.request=r;addEvent('Group block request submitted by '+name(r),'Guest');state.ui.guest='received';state.ui.admin='list';save();render();window.scrollTo(0,0);toast('Your group request has been submitted.');}
function requireState(condition,message){if(!condition)throw Error(message);}
function transition(action){const r=state.request,q=state.quote;
 if(action==='confirm-request'){requireState(r?.status==='Pending','Only a pending request can be confirmed.');r.status='Confirmed';addEvent('Request confirmed after availability review.','Sam Patel');}
 else if(action==='send-quote'){requireState(r?.status==='Confirmed'&&wizard,'Confirm the request before creating the quote.');requireState(wizard.rooms.reduce((s,x)=>s+x.qty,0)===r.single+r.double,'Select all requested rooms before sending.');requireState(wizard.sendEmail&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(wizard.email),'Choose Send quote and enter a valid email.');state.quote=JSON.parse(JSON.stringify(wizard));state.quote.status='Sent';state.quote.step=undefined;r.status='Converted';state.ui.admin='block';state.ui.guest='email';addEvent('Quote sent to '+state.quote.email+'.','Sam Patel');modal=null;wizard=null;}
 else if(action==='sign-contract'){requireState(q?.status==='Sent'&&!q.signature,'The quote must be sent before it can be signed.');const form=$('#signature-form');requireState(form?.reportValidity(),'Complete the signature fields.');const full=form.elements.fullname.value.trim();requireState(full&&form.elements.agree.checked,'Enter your name and accept the electronic signature terms.');requireState(signatureMode!=='draw'||drawn,'Draw your signature before continuing.');q.signature={name:full,mode:signatureMode,drawing:signatureMode==='draw'?drawData:null,date:'Sep 22, 2026'};state.ui.guest='payment';addEvent('Contract signed electronically by '+full+'.','Guest');}
 else if(action==='pay-deposit'){requireState(q?.signature&&!q.paid,'Sign the contract before paying the deposit.');const form=$('#payment-form');requireState(form?.reportValidity(),'Complete the demo payment form.');requireState(form.elements.card.value.replace(/\D/g,'')==='4242424242424242','Use the demo card 4242 4242 4242 4242.');requireState(/^\d{2}\s*\/\s*\d{2}$/.test(form.elements.expiry.value),'Use expiry format MM / YY.');requireState(/^\d{3}$/.test(form.elements.cvc.value),'Enter a 3-digit demo CVC.');q.paid=true;q.status='Confirmed';q.payment={amount:totals(q).deposit,last4:'4242',date:'Sep 22, 2026',reference:'PAY-008'};state.ui.guest='confirmed';state.ui.admin='block';addEvent('Contract signed and deposit received ('+money(totals(q).deposit)+').','System');}
 else if(action==='venue-confirm'){requireState(q?.status==='Confirmed'&&q.paid&&!q.venueConfirmed,'Guest signature and deposit are required for venue confirmation.');q.venueConfirmed=true;q.venueSignature={name:'Jordan Reyes',date:'Sep 22, 2026'};addEvent('Signed contract and deposit reviewed. Venue confirmed the booking.','Jordan Reyes');}
 else if(action==='book-reservation'){requireState(q?.venueConfirmed&&!state.reservation,'Confirm the signed group booking before converting.');state.reservation={id:'00031',groupCode:'GBR-008',status:'Pending Approval',notes:resWizard?.notes||'Group reservation for GBR-008. Assign rooms after approval.',color:resWizard?.color||'#fad659',assigned:false};q.status='Executed';state.ui.admin='reservation';modal=null;resWizard=null;addEvent('Group block converted to reservation #00031.','Sam Patel');}
 else if(action==='approve-reservation'){requireState(state.reservation?.status==='Pending Approval','Only a reservation pending approval can be confirmed.');state.reservation.status='Confirmed';addEvent('Reservation #00031 confirmed. Rooms and Meeting Hall reserved.','Jordan Reyes');}
 save();render();window.scrollTo(0,0);return {request:state.request?.status,groupBlock:state.quote?.status,reservation:state.reservation?.status};
}
function guestReceived(){const r=state.request;return `<div class="guest">${guestHeader()}<section class="event-hero"><div class="eyebrow" style="color:white">SUBMITTED</div><h1>Request received</h1><p>${esc(r.group)}</p></section><section class="received-card"><h2>Request details</h2>${[['Organization',r.organization],['Number of guests',r.guests],['Rooms requested',`${r.single+r.double} · ${r.single} single bed, ${r.double} double bed`],['Group type',r.type],['Dates',`${dates()} (${nights()} nights)`]].map(([k,v])=>`<div class="received-line"><label>${k}</label><span>${esc(v)}</span></div>`).join('')}<div class="row mt">${button('Back to form','back-to-form','primary')}${state.quote?button('Open your quote','open-email','primary'):''}</div>${state.quote?'':`<p class="hint">We will send your quote to ${esc(r.email)}.</p>`}</section>${guestFooter()}</div>`;}
function quoteRows(q=state.quote||wizard){return [...q.rooms.filter(x=>x.qty>0).map(x=>[x.type,x.qty,nights(),money(x.rate),money(x.qty*x.rate*nights())]),[`${q.space} (per day)`,q.spaceDays,'—',money(q.spaceRate),money(q.spaceDays*q.spaceRate)],[`Group Catering (per guest-day)`,q.cateringQty,'—',money(q.cateringRate),money(q.cateringQty*q.cateringRate)]];}
function quoteLines(q=state.quote||wizard){return q.rooms.filter(x=>x.qty>0).map(x=>line(`${esc(x.type)} × ${x.qty}`,money(x.qty*x.rate*nights()))).join('')+line(`${esc(q.space)} × ${q.spaceDays} days`,money(q.spaceDays*q.spaceRate))+line(`Group Catering × ${q.cateringQty} guest-days`,money(q.cateringQty*q.cateringRate));}
function totalLines(q=state.quote||wizard){const t=totals(q);return line('Amount total',money(t.subtotal))+line(`Tax (${q.tax?'10':'0'}%)`,money(t.tax))+line('Grand Total',money(t.total),'total');}
function guestEmail(){const q=state.quote;return `<div class="email-shell guest"><div class="email-top"><div><small>DEMO INBOX · ${esc(q.email)}</small><h3 class="mt">Your group quote · GBR-008</h3></div>${button('Back to request','view-received','link')}</div><article class="email-card">${img('0d92a.svg','Booking Ninjas')}<h1>Your group quote is ready</h1><p class="mb">Hi ${esc(state.request.first)},<br>Here is your quote for ${esc(state.request.group)}. Review your booking details, then sign and pay your deposit.</p><div class="email-meta"><div><label>TO</label><b>${esc(name())}</b><p>${esc(q.email)}</p></div><div><label>FROM</label><b>Cedar Valley Retreat & Conference Center</b><p>retreats@cedarvalley.example</p></div><div><label>QUOTE</label><b>GBR-008</b><p>${dates()}</p></div></div>${table(['Description','Qty','Nights','Price','Total'],quoteRows())}<div class="totals">${totalLines()}</div>${button(q.signature?'View booking':'Book Now',q.signature?'my-booking':'review-quote','primary wide-btn')}<p class="hint">50% deposit (${money(totals(q).deposit)}) is due when you sign. The quote is valid until Sep 28, 2026.</p></article></div>`;}
function quoteFacts(){const r=state.request;return `<div class="quote-facts"><div>${detail('Group',esc(r.group))}${detail('Dates',`${dates()} · ${nights()} nights`)}</div><div>${detail('Rooms',`${r.single+r.double} rooms · ${r.single} single bed, ${r.double} double bed`)}${detail('Billed to',esc(state.quote.billedTo))}</div></div>`;}
function docMini(type){const q=state.quote;return `<div class="doc-preview"><div class="mini-doc"><div class="doc-top"><b>CEDAR VALLEY</b><span>${type.toUpperCase()} · GBR-008</span></div><h3>${type==='beo'?'Banquet Event Order':'Group Booking Contract'}</h3><p style="font-size:6px;margin-bottom:8px">${esc(state.request.group)}</p>${type==='beo'?line('Dates',dates())+line('Rooms',`${state.request.single+state.request.double} rooms · ${nights()} nights`)+line('Meeting Hall',`${q.spaceDays} days · ${q.spaceTime}`)+line('Catering',`${q.cateringQty} guest-days`)+line('Total',money(totals(q).total)):line('Deposit',`50% · ${money(totals(q).deposit)}`)+line('Balance',`Due ${dueDate()}`)+line('Billed to',esc(q.billedTo))+line('Payment','Card')}<div style="border-top:1px solid #aaa;margin-top:14px;padding-top:4px;font-size:6px">Client signature &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Venue signature</div></div></div>`;}
function documentCard(type){const title=type==='beo'?'Banquet Event Order (BEO)':'Contract';return `<section class="panel"><div class="panel-body"><h3>${title}</h3><p class="caption mt">${type==='beo'?'BEO':'Contract'}_GBR-008.pdf · ${type==='beo'?'Version 2':state.quote.signature?'Signed electronically':'Needs your signature'}</p>${docMini(type)}<div class="row">${button('Open file','doc-'+type)}${button('Download','download-'+type)}</div></div></section>`;}
function guestReview(){return `<div class="guest">${guestHeader()}<div class="guest-main"><h1>Review your group booking</h1><p>Check the quote, the Banquet Event Order and the contract before you sign.</p><div class="guest-columns">${panel('Your quote',quoteFacts()+quoteLines()+line(`Taxes (${state.quote.tax?'10':'0'}%)`,money(totals().tax))+line('Grand Total',money(totals().total),'total'))}<div class="stack">${documentCard('beo')}${documentCard('contract')}</div></div><div class="guest-actions">${check('I have reviewed the quote, the BEO and the contract.','reviewed',false,'id="review-checkbox"')}${button('Continue to sign','continue-sign','primary',true)}</div></div>${guestFooter()}</div>`;}
function contractBody(){const r=state.request,t=totals();return `<div class="contract-section"><h3>1. Event</h3><p>${esc(r.group)}, ${dates()}, with ${r.single+r.double} rooms, the ${esc(state.quote.space)} for ${state.quote.spaceDays} days and group catering for ${r.guests} guests.</p></div><div class="contract-section"><h3>2. Payment</h3><p>50% deposit (${money(t.deposit)}) is due when the contract is signed. The remaining 50% (${money(t.total-t.deposit)}) is due seven days before arrival (${dueDate()}).</p></div><div class="contract-section"><h3>3. Changes and cancellation</h3><p>Room counts can be adjusted until Oct 30, 2026. Cancellations after that date are charged according to the venue policy.</p></div><div class="contract-section"><h3>4. Billing</h3><p>All rooms and add-ons are billed to the organizer on one invoice. Guests who prefer to pay separately may book with the group code.</p></div>`;}
function guestSign(){return `<div class="guest">${guestHeader()}<div class="guest-main"><h1>Sign your contract</h1><p>Read the contract, then add your signature to confirm the group booking.</p><div class="guest-columns">${panel('Contract · GBR-008',contractBody())}${panel('Sign here',`<form id="signature-form"><div class="signature-tabs">${button('Type','signature-type',signatureMode==='type'?'active':'')}${button('Draw','signature-draw',signatureMode==='draw'?'active':'')}</div>${field('Full name','fullname',name(),'text','required maxlength="100" id="signature-fullname"')}<div class="signature-pad">${signatureMode==='type'?`<div class="signature-name" id="signature-preview">${esc(name())}</div>`:`<canvas id="signature-canvas" class="signature-canvas" width="660" height="220" aria-label="Draw signature"></canvas>${button('Clear','clear-signature','link')}`}<small>Signed electronically · Sep 22, 2026</small></div>${check('I agree to the terms and to sign electronically.','agree',false,'required id="signature-agree"')}<div id="signature-error" class="error"></div><div class="mt">${button('Sign and continue','sign-contract','primary wide-btn',true)}</div></form>`)}</div></div>${guestFooter()}</div>`;}
function guestPayment(){const q=state.quote,t=totals();return '<div class="guest">'+guestHeader()+'<div class="guest-main"><h1>Pay your deposit</h1><p>Your contract is signed. Pay the 50% deposit to confirm the group booking.</p><div class="payment-demo">Demo payment · No charge is made. Use card 4242 4242 4242 4242, expiry 12 / 29 and CVC 123.</div><div class="guest-columns"><form id="payment-form" class="stack">'+panel('Billing Details','<div class="grid2">'+field('First Name','first',rFirst(),'text','readonly')+field('Last Name','last',state.request.last,'text','readonly')+'</div><div class="mt">'+field('Email','email',q.email,'email','readonly')+'</div>')+panel('Payment Method',field('Card Holder','cardname',name(),'text','required autocomplete="off"')+'<div class="mt">'+field('Card number','card','4242 4242 4242 4242','text','required inputmode="numeric" maxlength="23" autocomplete="off"')+'</div><div class="grid2 mt">'+field('Expiry','expiry','12 / 29','text','required maxlength="7" autocomplete="off"')+field('CVC','cvc','123','password','required inputmode="numeric" maxlength="3" autocomplete="off"')+'</div><p class="hint">Payment is simulated for this demo. Card details are not stored.</p>')+'</form>'+panel('Summary',line('Start Date',dateLabel(state.request.start))+line('End Date',dateLabel(state.request.end))+'<h3 class="mb mt">Accommodations</h3>'+q.rooms.map(x=>line(esc(x.type)+' × '+x.qty,money(x.qty*x.rate*nights()))).join('')+'<h3 class="mb mt">Add-ons</h3>'+line(esc(q.space)+' × '+q.spaceDays,money(t.space))+line('Group Catering × '+q.cateringQty,money(t.addons))+line('Subtotal',money(t.subtotal))+line('Taxes',money(t.tax))+line('Total',money(t.total),'total')+'<div class="deposit-box mt mb"><small>Due today · 50% deposit</small><strong>'+money(t.deposit)+'</strong><small>Balance '+money(t.total-t.deposit)+' due '+dueDate()+'</small></div><div id="payment-error" class="error mb"></div>'+button('Pay '+money(t.deposit),'pay-deposit','primary wide-btn'))+'</div></div>'+guestFooter()+'</div>';}
function rFirst(){return state.request.first;}
function guestConfirmed(){const r=state.request,q=state.quote,t=totals();const approved=state.reservation?.status==='Confirmed';return `<div class="guest">${guestHeader()}<div class="guest-main"><div class="confirmation-heading"><div class="success-circle">${img('a79b9.svg')}</div><h1>${approved?'Your reservation is confirmed':'Booking confirmed'}</h1><p>${approved?'The venue has approved your reservation. We look forward to welcoming your group.':'Your contract is signed and your deposit is paid. The venue team will finalize your reservation.'}</p></div><div class="guest-columns">${panel('Booking details',`<div class="quote-facts"><div>${detail('Group',esc(r.group))}${detail('Dates',`${dates()} · ${nights()} nights`)}${detail('Rooms',`${r.single+r.double} rooms · Meeting Hall · Group catering`)}</div><div>${detail('Paid today',`${money(t.deposit)} (deposit)`)}${detail('Balance',`${money(t.total-t.deposit)} due ${dueDate()}`)}${detail('Group code','GBR-008')}${state.reservation?detail('Reservation',`#00031 · ${badge(state.reservation.status)}`):''}</div></div>`)}${panel('What happens next',`<div class="next-step"><span class="dot">${approved?'✓':'1'}</span><p>${approved?'The venue team has approved your reservation.':'The venue team approves your reservation.'}</p></div><div class="next-step"><span class="dot">2</span><p>Assign guests to rooms, or share the group code so guests can book and pay for themselves.</p></div><div class="next-step"><span class="dot">3</span><p>You will receive your final invoice and arrival details before ${dateLabel(r.start).replace(/, \d{4}/,'')}.</p></div>`)}</div><div class="guest-actions">${button('View booking','guest-booking-details','primary')}${button('Add to calendar','calendar')}</div></div>${guestFooter()}</div>`;}
function adminRequest(){const r=state.request;return `<div class="admin">${sfNav()}${adminHeader('Group Block Request',r.group,'GBR-008 · Created Sep 08, 2026','',r.status)}<div class="admin-main"><div class="request-layout"><section class="panel"><div class="facts"><div class="fact"><label>Stay dates</label><strong>${dates()}</strong><small>${nights()} nights</small></div><div class="fact"><label>Rooms requested</label><strong>${r.single+r.double} rooms</strong><small>${r.single} single bed · ${r.double} double bed</small></div><div class="fact"><label>Group type</label><strong>${esc(r.type)}</strong></div></div><div class="panel-body grid2"><div><h3 class="mb">Organizer</h3>${detail('Contact',button(esc(name()),'contact','link'))}${detail('Organization',esc(r.organization))}${detail('Email',esc(r.email))}${detail('Address',esc(r.address))}</div><div><h3 class="mb">Special request</h3><div class="note-box">${esc(r.special)}</div></div></div></section>${panel('Next step',`<div class="next-step"><span class="dot">1</span><div><b>Review the request</b><p>Dates, rooms and special request.</p></div></div><div class="next-step"><span class="dot">2</span><div><b>Check availability</b><p>Rooms and the Meeting Hall for ${dates()}.</p><div class="row mt">${badge('Available')}${button('Open availability grid','availability','link')}</div></div></div><div class="next-step"><span class="dot">3</span><div><b>Confirm the request</b><p>${r.status==='Pending'?'Set the status to Confirmed.':'Status is '+r.status+'.'}</p></div></div>${r.status==='Pending'?button('Confirm Request','confirm-request','primary wide-btn')+`<div class="mt">${button('Convert To Group Block Code','start-wizard','wide-btn',true)}<p class="hint" style="text-align:center">Available after the request is confirmed.</p></div>`:state.quote?button('View Group Block','open-block','primary wide-btn'):button('Convert To Group Block Code','start-wizard','primary wide-btn')+'<p class="hint" style="text-align:center">Opens the New Group Booking wizard.</p>'}`)}</div></div></div>`;}
function requestPath(){return `<div class="status-path">${badge('Pending')}<i></i>${badge(state.request.status==='Pending'?'Confirmed':state.request.status)}${state.quote?'<i>'+ '</i>'+badge('Converted'):''}</div>`;}
function roomTable(q=state.quote){return table(['#','ROOM TYPE','QUANTITY','RATE','TOTAL AMOUNT'],q.rooms.filter(x=>x.qty>0).map((x,i)=>[i+1,`${esc(x.type)} (${nights()} nights)`,x.qty,money(x.rate),money(x.qty*x.rate*nights())]));}
function adminBlock(){const r=state.request,q=state.quote,t=totals();const info=panel('Banquet Event Order',detail('Group Name',esc(r.group))+detail('Status',badge(q.status))+detail('Contact',button(esc(name()),'contact','link'))+detail('Start Date → End Date',dateLabel(r.start)+' → '+dateLabel(r.end))+detail('Group Type',esc(r.type))+detail('Payment options','Card')+detail('Group Block Request',button('GBR-008','open-request','link')),badge('PMS'),'block-info');const summary=panel('Summary',line('Rooms',money(t.rooms))+line('Space',money(t.space))+line('Add-on',money(t.addons))+line('Taxes',money(t.tax))+line('Total Amount',money(t.total),'block-total')+line(q.paid?'Deposit paid (50%)':'Deposit due (50%)',money(t.deposit))+('<div class="mt">'+(q.status==='Sent'?'<p class="hint">Quote sent. Awaiting guest signature and deposit.</p>':q.status==='Confirmed'&&!q.venueConfirmed?button('Review & Confirm Booking','review-booking','primary wide-btn'):q.venueConfirmed&&!state.reservation?button('Convert To Reservation','start-reservation','primary wide-btn'):button('View Reservation #00031','open-reservation','primary wide-btn'))+'</div>'),'','block-summary');const agenda=panel('Agenda <span class="round-count">3</span>',table(['#','AGENDA','GUESTS','START TIME','END TIME','LOCATION','STATUS'],[[1,'Arrival and Check-in',r.guests,'03:00 PM','05:00 PM','Main Lodge Lobby',badge(q.status==='Sent'?'Pending':'Confirmed')],[2,'Leadership Sessions',r.guests,'09:00 AM','05:00 PM','Meeting Hall',badge(q.status==='Sent'?'Pending':'Confirmed')],[3,'Group Dinner',r.guests,'06:30 PM','08:30 PM','Dining Hall',badge(q.status==='Sent'?'Pending':'Confirmed')]]),'','table-panel');const space=panel('Space <span class="round-count">1</span>',table(['#','SPACE','QUANTITY','RATE','TOTAL AMOUNT'],[[1,esc(q.space)+' (per day)',q.spaceDays,money(q.spaceRate),money(t.space)]]),button('Inventory','availability'),'table-panel');const rooms=panel('Room Setup <span class="round-count">3</span>',roomTable(),button('Inventory','availability'),'table-panel');const addons=panel('Add-on <span class="round-count">1</span>',table(['#','ADD-ON','QUANTITY','RATE','TOTAL AMOUNT'],[[1,'Group Catering (per guest-day)',q.cateringQty,money(q.cateringRate),money(t.addons)]]),badge('POS'),'table-panel');const contract=panel('Contract','<p class="caption">GBR-008</p><div class="grid2"><div class="note-box">'+detail('Group Name',esc(r.group))+'</div><div class="note-box">'+detail('Status',q.signature?'Confirmed':'Pending')+'</div></div><div class="note-box mt"><h3 class="mb">Terms & Conditions</h3><p class="muted">50% deposit ('+money(t.deposit)+') is due when the contract is signed; the remaining balance is due seven days before arrival ('+dueDate()+'). Rooms, Meeting Hall and catering are billed to '+esc(r.organization)+' on one invoice.</p></div><div class="grid2 mt"><div class="note-box"><h3 class="mb">Client Signature</h3><div class="signature-name">'+(q.signature?esc(q.signature.name):'Awaiting signature')+'</div><p class="hint">'+(q.signature?'Signed electronically · Sep 22, 2026':'Needs guest signature')+'</p></div><div class="note-box"><h3 class="mb">Venue Signature</h3><div class="signature-name">'+(q.venueConfirmed?'Jordan Reyes':'Awaiting review')+'</div><p class="hint">'+(q.venueConfirmed?'Events Manager · Sep 22, 2026':'Confirm after guest signature and deposit')+'</p></div></div>',badge(q.signature?'Confirmed':'Pending'),'block-contract');const notes=panel('Notes <span class="round-count">'+state.events.length+'</span>','<div id="notes">'+state.events.slice().reverse().map(x=>'<div class="note-item"><p>'+esc(x.text)+'</p><small>'+x.date+' · '+esc(x.actor)+'</small></div>').join('')+'</div>',button('Add Note','add-note','primary'));const files=panel('Files <span class="round-count">2</span>','<div class="file-item"><div><b>Contract_GBR-008.pdf</b><p class="hint">'+(q.signature?'Signed electronically · Sep 22, 2026':'Needs guest signature')+'</p></div><div class="row">'+badge(q.signature?'Signed':'Pending')+button('View','doc-contract','link')+'</div></div><div class="file-item"><div><b>BEO_GBR-008.pdf</b><p class="hint">Banquet Event Order · Version 2</p></div><div class="row">'+badge('Final')+button('View','doc-beo','link')+'</div></div>');return '<div class="admin block-page">'+sfNav()+'<header class="admin-header"><div>'+breadcrumbs([['Group Block Requests','request-list'],['GBR-008']])+'<div class="row"><h1>GBR-008</h1>'+badge(q.status)+'</div><div class="sub">'+esc(r.type)+' · '+esc(r.group)+' · '+button(esc(name()),'contact','link')+'</div></div><div class="row">'+button('GBR-008 ↗','open-request')+button('View BEO','doc-beo')+button('View Contract','doc-contract')+(q.venueConfirmed&&!state.reservation?button('Convert','start-reservation'):'')+'</div></header><div class="admin-main block-layout"><aside class="stack">'+info+summary+'</aside><div class="stack">'+agenda+space+rooms+addons+contract+notes+files+'</div></div></div>';}
let availability=null;
function breadcrumbs(items){return '<nav class="breadcrumbs" aria-label="Breadcrumb"><ol>'+items.map(([text,action])=>'<li>'+(action?button(esc(text),action,'link'):('<span aria-current="page">'+esc(text)+'</span>'))+'</li>').join('')+'</ol></nav>';}
function availabilityDateField(label,name,value){return '<label class="field calendar-date-field"><span>'+label+'</span><div class="calendar-date-input"><input name="'+name+'" type="date" required value="'+value+'"><span class="calendar-date-value">'+dateLabel(value)+'</span>'+img('a73ab.svg')+'</div></label>';}
function availabilityDefaults(){const r=state.request||defaults;return {start:r.start,end:r.end,type:'Nightly',property:'Cedar Valley',room:'All',floor:'All',only:false,sort:'Property',desc:false,zoom:64};}
function captureAvailability(){const f=$('#availability-filters');if(!f.reportValidity())return false;const v=Object.fromEntries(new FormData(f));if(Date.parse(v.end)<=Date.parse(v.start)){toast('End date must be after start date.',true);return false;}availability={...availability,...v,only:!!v.only};return true;}
function availabilityDate(s,offset){const d=new Date(s+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10);}
function availabilityUnits(){const rows=[];for(const [type,count,prefix,floor]of [['Standard Single Room',12,100,'1'],['Standard Double Room',7,200,'2'],['Cabin',4,'Cabin ','Ground'],['Meeting Hall',6,'MH-','Ground']])for(let i=1;i<=count;i++)rows.push({type,unit:typeof prefix==='number'?String(prefix+i):prefix+i,floor,index:i});return rows;}
function availabilityBookings(row){const background={102:['D. Okafor','2026-11-09','2026-11-12'],103:['M. Webb','2026-11-19','2026-11-22'],201:['E. Rossi','2026-11-19','2026-11-23'],203:['Out of order','2026-11-16','2026-11-19'],'Cabin 4':['N. Patel','2026-11-09','2026-11-12']};const b=[];if(background[row.unit]){const [label,start,end]=background[row.unit];b.push({label,start,end,status:label==='Out of order'?'Out of order':'Confirmed'});}if(state.reservation){const r=state.request,q=state.quote;const qty=row.type==='Meeting Hall'?1:q.rooms.find(x=>x.type===row.type)?.qty||0;if(row.index<=qty)b.push({label:r.organization||name(r),start:r.start,end:row.type==='Meeting Hall'?availabilityDate(r.start,q.spaceDays):r.end,status:state.reservation.status,demo:true});}return b;}
function adminAvailability(){availability??=availabilityDefaults();const a=availability;const windowStart=availabilityDate(a.start,-3);const days=Array.from({length:Math.max(16,Math.min(31,nights({start:a.start,end:a.end})+6))},(_,i)=>availabilityDate(windowStart,i));const base=availabilityUnits();let rows=base.filter(r=>(a.room==='All'||r.type===a.room)&&(a.floor==='All'||r.floor===a.floor)&&(!a.only||!availabilityBookings(r).some(b=>b.start<a.end&&b.end>a.start)));if(a.room==='All'&&a.floor==='All'&&!a.only)rows=rows.filter(r=>r.type==='Meeting Hall'||r.type==='Cabin'||r.index<=3||state.pickup?.active&&state.pickup.slots.some(s=>s.unit===r.unit&&s.type===r.type&&s.guest));rows.sort((x,y)=>a.sort==='Unit'?x.unit.localeCompare(y.unit,undefined,{numeric:true}):a.sort==='Room Type'?x.type.localeCompare(y.type)||x.index-y.index:0);if(a.desc)rows.reverse();const filters=`<form id="availability-filters" class="availability-filters">${select('Type','type',a.type,['Nightly'])}${availabilityDateField('Start Date','start',a.start)}${availabilityDateField('End Date','end',a.end)}${select('Property','property',a.property,['Cedar Valley'])}${select('Room Type','room',a.room,['All','Standard Single Room','Standard Double Room','Cabin','Meeting Hall'])}${select('Floor','floor',a.floor,['All','1','2','Ground'])}${check('Only Available','only',a.only)}${button(img('3c1cb.svg')+'Search','availability-search','primary icon-text')}${button(img('9d4e8.svg')+'Reset all','availability-reset','icon-text')}</form>`;const head=`<div class="calendar-header"><div class="calendar-label">Property</div><div class="calendar-label">Room Type</div><div class="calendar-label">Unit</div><div class="calendar-month">${new Date(a.start+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'})}<div class="calendar-days">${days.map(d=>`<div class="calendar-day ${d>=a.start&&d<a.end?'requested':new Date(d+'T12:00:00Z').getUTCDay()%6===0?'weekend':''}">${new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'})}<br>${Number(d.slice(8))}</div>`).join('')}</div></div></div>`;const body=rows.map(row=>{const bookings=availabilityBookings(row);return `<div class="calendar-row"><div class="calendar-label">Cedar Valley</div><div class="calendar-label">${row.type}</div><div class="calendar-label unit-label">${img(row.type==='Meeting Hall'?'096db.svg':'eb333.svg')}${row.unit}</div><div class="calendar-track">${days.map(d=>`<div class="calendar-cell ${d>=a.start&&d<a.end?'requested':new Date(d+'T12:00:00Z').getUTCDay()%6===0?'weekend':''}"></div>`).join('')}${bookings.map(b=>{const start=Math.max(0,Math.round((Date.parse(b.start)-Date.parse(windowStart))/86400000));const end=Math.min(days.length,Math.round((Date.parse(b.end)-Date.parse(windowStart))/86400000));return end>start?`<button class="calendar-booking ${b.status==='Confirmed'?'confirmed':b.status==='Out of order'?'out-of-order':'pending'}" ${b.demo?'data-action="availability-booking"':''} style="left:calc(${start} * var(--day-width) + 2px);width:calc(${end-start} * var(--day-width) - 4px)" title="${esc(b.label)} · ${b.status} · ${dateLabel(b.start)} – ${dateLabel(b.end)}"><b>${esc(b.label)}</b>${b.status==='Out of order'?'':'<span>'+b.status+'</span>'}</button>`:'';}).join('')}</div></div>`;}).join('');return `<div class="admin availability-page">${sfNav()}<div class="admin-main"><div class="availability-top">${state.request?breadcrumbs([['Group Block Requests','request-list'],['GBR-008',state.quote?'open-block':'open-request'],['Availability']]):'<span></span>'}${button(img('eb609.svg')+'New Reservation','availability-new','primary icon-text')}</div>${filters}<section id="availability-grid" class="availability-grid" style="--day-width:${a.zoom}px"><div class="availability-toolbar"><div class="row"><label class="calendar-zoom"><span class="sr-only">Timeline zoom</span><span class="zoom-track"></span><span class="zoom-handle" style="left:${(a.zoom-40)/56*100}%">${img('ef5da.svg')}</span><input name="availability-zoom" type="range" min="40" max="96" value="${a.zoom}" aria-label="Timeline zoom"></label><button class="calendar-icon" data-action="availability-zoom-out" aria-label="Zoom out">${img('c424a.svg')}</button><span>Day</span><button class="calendar-icon" data-action="availability-zoom-in" aria-label="Zoom in">${img('2cf15.svg')}</button><span>Sort by</span><select name="availability-sort" aria-label="Sort by">${['Property','Room Type','Unit'].map(x=>'<option '+(x===a.sort?'selected':'')+'>'+x+'</option>').join('')}</select><button class="calendar-icon" data-action="availability-sort" aria-label="Reverse sort">${img('2880f.svg')}</button></div><button class="calendar-icon" data-action="availability-reset" aria-label="Reset timeline">${img('39b0c.svg')}</button></div><div class="calendar-scroll"><div class="calendar-inner" style="width:calc(370px + ${days.length} * var(--day-width))"><div class="calendar-scroll-indicator"></div>${head}${body||'<p class="empty-grid">No units match these filters.</p>'}</div></div><div class="calendar-legend">${[['available','Available'],['confirmed','Confirmed'],['pending','Pending Approval'],['out-of-order','Out of order'],['requested','Requested stay']].map(([cls,label])=>`<span><i class="${cls}"></i>${label}</span>`).join('')}<span>Showing ${rows.length} of ${base.length} units</span></div></section></div></div>`;}

function reservationAmount(amount){return '<div class="reservation-amount"><strong>'+money(amount)+'</strong><small>+Tax '+money(state.quote.tax?Math.round(amount*10)/100:0)+'</small></div>';}
function reservationRooms(){let i=0;const q=state.quote,v=state.reservation;const rows=q.rooms.flatMap(x=>Array.from({length:x.qty},()=>{const id=++i;return ['<div class="reservation-room-cell"><span class="room-photo-placeholder"></span><div><small>From Cedar Valley Retreat & Conference Center</small><strong>'+esc(x.type)+'</strong>'+button(v.assigned?'Room '+(100+id):'Assign Room','assign-rooms','link')+'</div></div>','<strong>'+esc(name())+'</strong>',dateLabel(state.request.start),dateLabel(state.request.end),'1 / 0',v.status,nights()+' nights',reservationAmount(x.rate*nights()),reservationAmount(x.rate*nights()),'<button class="room-action" data-action="room-'+id+'" aria-label="Room '+id+' actions">'+img('a2374.svg')+'</button>'];}));const indexes=rows.length===22?[0,1,2,12,13,18,19]:Array.from({length:Math.min(7,rows.length)},(_,j)=>j);return '<div class="reservation-table reservation-rooms-table">'+table(['ROOM','GUEST','START DATE','END DATE','GUESTS','STATUS','LENGTH','ROOM ONLY','TOTAL','ACTIONS'],state.ui.allRooms?rows:indexes.map(j=>rows[j]))+'<p class="hint table-hint">Showing '+(state.ui.allRooms?rows.length:indexes.length)+' of '+rows.length+' rooms · '+button(state.ui.allRooms?'Show less':'View all','all-rooms','link')+'</p></div>';}
function adminReservation(){const r=state.request,q=state.quote,v=state.reservation,t=totals(),tab=state.ui.resTab||'Details';const count=q.rooms.reduce((n,x)=>n+x.qty,0);const pending=v.status==='Pending Approval';const status=pending?'Pending':'Confirmed';const space='<div class="reservation-table reservation-space-table">'+table(['SPACE','DESCRIPTION','START DATE','END DATE','TIME','DAYS','STATUS','AMOUNT'],[[esc(q.space),'Venue for workshops and leadership sessions',dateLabel(r.start),spaceDates(q).split(' – ')[1],esc(q.spaceTime),q.spaceDays,badge(status),reservationAmount(t.space)]])+'</div>';const items='<div class="reservation-table reservation-items-table">'+table(['ITEM','START DATE','END DATE','CALCULATION RULE','QTY','STATUS','AMOUNT',''],[['<div class="reservation-item-cell"><span class="item-photo-placeholder"></span><div><strong>Group Catering (per guest-day)</strong><small>Three daily meals for the group</small></div></div>',dateLabel(r.start),spaceDates(q).split(' – ')[1],'Per Person',q.cateringQty,badge(status),reservationAmount(t.addons),button('Remove','reservation-remove-item','link')]])+'</div>';let details='<h2 class="reservation-section-title">Space <span>1</span></h2>'+space+'<h2 class="reservation-section-title">Reservation Rooms <span>('+count+'/'+count+')</span></h2>'+reservationRooms()+'<div class="reservation-add">'+button('Add','reservation-add-room')+'</div><h2 class="reservation-section-title">Items <span>(1)</span></h2>'+items;
if(tab==='Payments')details=panel('Payments',table(['PAYMENT','DATE','METHOD','STATUS','AMOUNT'],[['PAY-008','Sep 22, 2026','Card ending 4242',badge('Paid'),money(q.payment?.amount||t.deposit)]])+'<p class="hint">Balance '+money(t.total-(q.payment?.amount||t.deposit))+' due '+dueDate()+'.</p>',button('View Invoice','invoice'));
if(tab==='Files')details=panel('Files','<div class="file-item"><b>Contract_GBR-008.pdf · Signed</b>'+button('View','doc-contract','link')+'</div><div class="file-item"><b>BEO_GBR-008.pdf · Version 2</b>'+button('View','doc-beo','link')+'</div>');
if(tab==='Activities')details=panel('Activities',state.events.slice().reverse().map(x=>'<div class="note-item"><p>'+esc(x.text)+'</p><small>'+x.date+' · '+esc(x.actor)+'</small></div>').join(''));
const info='<section class="reservation-info-card"><h2>Reservation Info</h2><div class="reservation-inner"><div class="reservation-date-row">'+availabilityDateField('Start Date','reservation-start',r.start)+availabilityDateField('End Date','reservation-end',r.end)+'</div><div class="reservation-meta">'+detail('Booked by',esc(name()))+detail('Taxes enabled',q.tax?'True':'False')+detail('Taxes',money(t.tax))+'</div><div class="reservation-card-footer"><div class="row">'+button('Add room','reservation-add-room')+button('Add item','reservation-add-item')+'</div><div class="reservation-card-total"><span>Grand Total</span><strong>'+money(t.total)+'</strong></div></div></div></section>';
const billing='<section class="reservation-info-card"><h2>Billing Info</h2><div class="reservation-inner"><div class="reservation-contact-row">'+field('Contact Name','billingContact',name(),'text','readonly')+button('Change','reservation-change-contact')+'</div><div class="reservation-meta">'+detail('Email',esc(q.email))+detail('Invoice',button('INV-00031','invoice','link'))+'</div><div class="reservation-card-footer"><div class="row">'+button('Invoice','invoice')+button('Payments','reservation-tab-Payments')+'</div><div class="reservation-card-total"><span>Balance Due</span><strong>'+money(t.total-(q.payment?.amount||t.deposit))+'</strong></div></div></div></section>';
return '<div class="admin reservation-page reservation-v2">'+sfNav()+'<div class="reservation-page-body"><header class="reservation-record-header"><div><div class="row"><span>Reservation</span><h1>#00031</h1></div><div class="sub">Group Block &nbsp;'+button('GBR-008','open-block','link')+'</div></div><div class="row">'+button(v.checkedIn?'Checked-In':'Check-In','check-in','',pending||v.checkedIn)+button(v.checkedOut?'Checked-Out':'Check-Out','check-out','',pending||!v.checkedIn||v.checkedOut)+(pending?button('Confirm Reservation','approve-reservation','primary'):'')+'</div></header><div class="reservation-status-path">'+['Cancelled','Pending Approval','Confirmed'].map(x=>'<div>'+(x===v.status?badge(x):'<strong>'+x+'</strong>')+'</div>').join('')+'</div><div class="reservation-info-cards">'+info+billing+'</div><section class="reservation-details-card"><nav class="tab-bar">'+['Details','Payments','Files','Activities'].map(x=>'<button data-action="reservation-tab-'+x+'" class="'+(tab===x?'active':'')+'">'+x+'</button>').join('')+'</nav>'+details+'</section></div></div>';}

function adminInvoice(){const t=totals();return `<div class="admin">${sfNav()}${adminHeader('BN Invoice','INV-00031','Reservation #00031 · GBR-008',button('Back to reservation','open-reservation')+button('Download Invoice','download-invoice'))}<div class="admin-main"><div class="request-layout">${panel('Invoice · Deposit paid',`<div class="grid2 mb"><div>${detail('Billed to',esc(name()))}${detail('Organization',esc(state.request.organization))}${detail('Email',esc(state.quote.email))}</div><div>${detail('Invoice status',badge('Paid')+' · 50% deposit')}${detail('Payment reference','PAY-008 · Card ending 4242')}${detail('Balance due date',dueDate())}</div></div>`+table(['DESCRIPTION','QTY','NIGHTS','RATE','AMOUNT'],quoteRows()))}${panel('Payment summary',totalLines()+line('Deposit paid',money(t.deposit))+line('Remaining balance',money(t.total-t.deposit))+'<p class="hint">Demo payment received Sep 22, 2026. No real charge was made.</p>')}</div></div></div>`;}
function contactView(){const r=state.request||defaults;return `<div class="admin">${sfNav()}${adminHeader('Contact',name(r),esc(r.organization),button('Back to requests','request-list'))}<div class="admin-main">${panel('Contact details',`<div class="grid2">${detail('Full name',esc(name(r)))}${detail('Organization',esc(r.organization))}${detail('Email',esc(r.email))}${detail('Address',esc(r.address))}</div>${state.request?button('View request GBR-008','open-request','primary'):''}`)}</div></div>`;}
function render(){const guestViews={form:guestForm,received:guestReceived,email:guestEmail,review:guestReview,sign:guestSign,payment:guestPayment,confirmed:guestConfirmed};const adminViews={list:adminList,request:adminRequest,block:adminBlock,availability:adminAvailability,reservation:adminReservation,invoice:adminInvoice,contacts:contactView};$('#demo').innerHTML=demoBar();const views=state.ui.app==='guest'?guestViews:adminViews;try{$('#app').innerHTML=(views[state.ui[state.ui.app]]||views[state.ui.app==='guest'?'form':'list'])();}catch{$('#app').innerHTML=state.ui.app==='guest'?guestForm():adminList();}renderOverlay();if(state.ui.app==='guest'&&state.ui.guest==='sign'&&signatureMode==='draw')bindCanvas();}
function stepper(names,step){return `<div class="stepper">${names.map((x,i)=>(i?'<i></i>':'')+`<div class="step ${i+1===step?'active':i+1<step?'complete':''}"><span class="dot">${i+1}</span><span>${x}</span></div>`).join('')}</div>`;}
function wizardBody(){const q=wizard,r=state.request,t=totals(q);const count=q.rooms.reduce((s,x)=>s+x.qty,0);const singles=q.rooms.filter(x=>x.bed==='Single').reduce((s,x)=>s+x.qty,0);const double=count-singles;let body='';if(q.step===1)body=`<div class="band">Group Block Info</div><div class="grid2">${field('Code','code','GBR-008','text','readonly')}${field('Status','status','Confirmed','text','readonly')}${field('Start Date *','start',r.start,'date','readonly')}${field('End Date *','end',r.end,'date','readonly')}${field('Group Type','type',r.type,'text','readonly')}${field('Group Name','group',r.group,'text','readonly')}</div><div class="mt">${field('Pricing Type','pricing','Nightly','text','readonly')}</div><div class="mt">${textarea('Special Request','special',r.special,'readonly')}</div>`;
 else if(q.step===2)body=`<div class="band">Space</div><div class="grid2">${select('Space','space',q.space,['Meeting Hall'])}${select('Setup layout','layout',q.layout,['Classroom','Theater','U-shape','Banquet'])}</div><div class="grid3 mt">${field('Days','spaceDays',q.spaceDays,'number','required min="1" max="14"')}${field('Time','spaceTime',q.spaceTime,'text','required')}${field('Guests','guests',r.guests,'number','readonly')}</div><div class="row mt">${badge('Available')}<small>Capacity 60 · ${money(q.spaceRate)} per day · free for the requested dates</small></div><div class="mt">${check('Overnight stay: add rooms for this group','overnight',true,'disabled')}</div><div class="band">Rooms</div><div class="row between mb"><div class="row">${button('Select room types','room-picker')}${button('Auto select requested rooms','auto-rooms')}</div></div>${table(['ROOM TYPE','BED TYPE','ROOMS','AVAILABLE','RATE / NIGHT'],q.rooms.map((x,i)=>[esc(x.type),x.bed,`<input aria-label="${esc(x.type)} quantity" class="room-input" name="room-${i}" type="number" min="0" max="${x.available}" value="${x.qty}">`,x.available,`<input aria-label="${esc(x.type)} nightly rate" class="room-input rate-input" name="rate-${i}" type="number" min="1" max="2000" value="${x.rate}">`]))}<div class="row mt">${badge(count===r.single+r.double&&singles===r.single&&double===r.double?'Matches request':'Select rooms')}<small>${count} of ${r.single+r.double} rooms · Single bed ${singles}/${r.single} · Double bed ${double}/${r.double}</small></div><div class="band">Add-ons</div>${button(q.cateringQty?'Edit add-on':'Add add-on','addon-picker')}${q.cateringQty?table(['ADD-ON','QTY','RATE','TOTAL'],[['Group Catering (per guest-day)',q.cateringQty,money(q.cateringRate),money(t.addons)]]):'<p class="hint">Add group catering for '+r.guests+' guests × '+nights()+' days.</p>'}`;
 else if(q.step===3)body=`<div class="band">Billing Information</div><div class="grid2">${field('Billed to (Person) *','billedTo',q.billedTo,'text','required')}${check('Taxes Enabled','tax',q.tax)}</div><p class="hint mt">All rooms and add-ons go on one invoice for the organizer. Guests who prefer to pay separately can book with the group code.</p>`;
 else body=`<div class="panel"><div class="panel-body"><h3 class="mb">Space, rooms & add-ons</h3>${quoteLines(q)}</div></div><div class="panel mt"><div class="panel-body">${totalLines(q)}</div></div><div class="mt mb">${check('Send quote to customer e-mail','sendEmail',q.sendEmail)}</div>${field('Email','email',q.email,'email','required')}`;
 return `<form id="wizard-form" class="wizard">${stepper(['Group Block Info','Space, rooms & add-ons','Billing','Review & send'],q.step)}<div class="wizard-count">${esc(r.type)} · ${count} of ${r.single+r.double} rooms selected · Single Bed ${singles}/${r.single} · Double Bed ${double}/${r.double}</div>${body}<div id="wizard-error" class="error"></div></form>`;}
function documentHTML(type){const q=state.quote,r=state.request,t=totals();return `<article class="doc-full"><div class="doc-top"><b>CEDAR VALLEY</b><span>${type==='beo'?'BEO':type==='invoice'?'INVOICE':'CONTRACT'} · GBR-008</span></div><h1>${type==='beo'?'Banquet Event Order':type==='invoice'?'Invoice · INV-00031':'Group Booking Contract'}</h1><p>${esc(r.group)}</p><h2>Booking details</h2><div class="grid2">${detail('Dates',`${dates()} · ${nights()} nights`)}${detail('Organizer',`${esc(name())} · ${esc(r.organization)}`)}${detail('Rooms',`${r.single+r.double} rooms · ${r.single} single bed, ${r.double} double bed`)}${detail('Guests',r.guests)}</div>${type==='contract'?contractBody():`<h2>Rooms, space & catering</h2>${table(['DESCRIPTION','QUANTITY','NIGHTS','RATE','TOTAL'],quoteRows())}<div class="mt">${totalLines()}</div>${type==='beo'?'<h2>Event schedule</h2>'+table(['AGENDA','TIME','LOCATION'],[['Arrival and Check-in','3:00 PM – 5:00 PM','Main Lodge Lobby'],['Leadership Sessions',esc(q.spaceTime),esc(q.space)],['Group Dinner','6:30 PM – 8:30 PM','Dining Hall']]):line('Deposit paid',money(t.deposit))+line('Balance due '+dueDate(),money(t.total-t.deposit))}`}${type!=='invoice'?`<div class="signature-block"><div><b>Client signature</b><p>${q.signature?esc(q.signature.name):'________________________'}</p><small>${q.signature?'Signed electronically · Sep 22, 2026':'Date: ____ / ____ / ________'}</small></div><div><b>Venue signature</b><p>${q.venueConfirmed?'Jordan Reyes':'________________________'}</p><small>${q.venueConfirmed?'Events Manager · Sep 22, 2026':'Date: ____ / ____ / ________'}</small></div></div>`:''}<p class="hint mt">Interactive demo document · GBR-008</p></article>`;}
function renderOverlay(){let title='',body='',footer='',size='',guest=false;if(!modal){$('#overlay').innerHTML='';document.body.style.overflow='';return;}
 if(modal==='wizard'){title='New Group Booking for GBR-008';body=wizardBody();footer=button(wizard.step===1?'Cancel':'Back',wizard.step===1?'close-modal':'wizard-back')+button(wizard.step===4?'Send':'Next',wizard.step===4?'send-quote':'wizard-next','primary');}
 else if(modal==='room-picker'){title='Select room types';body=`<p class="mb">Choose rooms matching the request: ${state.request.single} single bed · ${state.request.double} double bed.</p>${table(['ROOM TYPE','BED TYPE','AVAILABLE','SELECTED'],wizard.rooms.map((x,i)=>[x.type,x.bed,x.available,`<input aria-label="${x.type} quantity" class="room-input" type="number" min="0" max="${x.available}" value="${x.qty}" name="pick-${i}">`]))}<div id="picker-error" class="error"></div>`;footer=button('Cancel','picker-cancel')+button('Apply','picker-apply','primary');}
 else if(modal==='addon-picker'){title='Add-on picker';body=`<form id="addon-form"><div class="band">Group Catering (per guest-day)</div><p class="muted mb">Meals for ${state.request.guests} guests × ${nights()} days.</p><div class="grid2">${field('Quantity (guest-days)','cateringQty',wizard.cateringQty||state.request.guests*nights(),'number','required min="1" max="10000"')}${field('Rate per guest-day','cateringRate',wizard.cateringRate,'number','required min="1" max="500"')}</div></form>`;footer=button('Cancel','picker-cancel')+button('Add to quote','addon-apply','primary');}
 else if(modal==='reservation'){title='New Reservation';body=stepper(['Reservation info','Review & book'],resWizard.step)+(resWizard.step===1?`<form id="reservation-form"><div class="grid2">${field('GB Code','code','GBR-008','text','readonly')}${field('Group Name','group',state.request.group,'text','readonly')}</div><div class="band">Reservation Info</div><div class="reservation-status-row">${field('Status','status','Pending Approval','text','disabled')}<label class="field color-field"><span>Color</span><input name="color" type="color" value="${resWizard.color}" aria-label="Color"></label></div><div class="mt">${textarea('Notes','notes',resWizard.notes)}</div></form>`:`<div class="panel"><div class="panel-body">${quoteLines()}</div></div><div class="panel mt"><div class="panel-body">${totalLines()}</div></div><p class="hint mt">Deposit ${money(totals().deposit)} already received. It will be carried to the reservation invoice.</p>`);footer=button(resWizard.step===1?'Cancel':'Back',resWizard.step===1?'close-modal':'reservation-back')+button(resWizard.step===1?'Next':'Book',resWizard.step===1?'reservation-next':'book-reservation','primary');}
 else if(modal.startsWith('doc-')){const type=modal.slice(4);title=type==='beo'?'BEO_GBR-008.pdf':type==='invoice'?'Invoice_INV-00031.pdf':'Contract_GBR-008.pdf';body=documentHTML(type);footer=button('Close','close-modal')+button('Download','download-'+type,'primary');size='large';guest=state.ui.app==='guest';}
 else if(modal==='availability-help'){title='New Reservation';body='<p>To reserve this group, confirm the signed group booking and then convert it to a reservation.</p>';footer=button('Close','close-modal')+(state.quote?button('View Group Block','open-block','primary'):state.request?button('Review request','open-request','primary'):'');size='small';}
 else if(modal==='reservation-locked-services'){title='Reservation services';body='<p>Rooms and catering were converted from the signed group quote. Review the group booking or availability before changing the reservation.</p>'+roomTable();footer=button('Close','close-modal')+button('Availability','reservation-show-availability')+button('View Group Block','open-block','primary');}
 else if(modal==='reservation-contact'){title='Billing contact';body=detail('Name',esc(name()))+detail('Email',esc(state.quote.email))+detail('Organization',esc(state.request.organization));footer=button('Close','close-modal')+button('Open Contact','contact','primary');size='small';}
 else if(modal==='reset'){title='Reset the demo?';body='<p>Clear the request, quote, signatures, deposit and reservation. Both apps return to the beginning with an empty request form.</p>';footer=button('Keep current story','close-modal')+button('Reset demo','confirm-reset','primary');size='small';}
 else if(modal==='review-booking'){title='Review signed group booking';body=`<div class="grid2">${detail('Client signature',esc(state.quote.signature.name)+' · Sep 22, 2026')}${detail('Deposit',badge('Paid')+' '+money(totals().deposit))}${detail('Quote total',money(totals().total))}${detail('Rooms',`${state.request.single+state.request.double} rooms · ${nights()} nights`)}</div><p class="callout">Confirming adds the venue signature from Jordan Reyes and enables conversion to reservation.</p>`;footer=button('Cancel','close-modal')+button('Confirm Booking','venue-confirm','primary');}
 else if(modal==='add-note'){title='Add Note';body=`<form id="note-form">${textarea('Note','note','','required maxlength="2000"')}</form>`;footer=button('Cancel','close-modal')+button('Save Note','save-note','primary');size='small';}
 else if(modal==='assign-label'){title='Assign Label';body=`<form id="label-form">${field('Label for GBR-008','label',state.request?.label||'Leadership retreat','text','required maxlength="60"')}</form><p class="hint">Apply a label to the active demo request.</p>`;footer=button('Cancel','close-modal')+button('Apply Label','save-label','primary');size='small';}
 else if(modal==='assign-rooms'){title='Assign rooms · #00031';body='<p>Assign the selected 22 accommodations to the Horizon Foundation reservation. Standard rooms and cabins will receive unique room numbers.</p>'+roomTable();footer=button('Cancel','close-modal')+button('Assign Rooms','confirm-assign','primary');}
 else if(modal==='guest-booking'){title='Your booking · GBR-008';body=quoteFacts()+quoteLines()+totalLines()+line('Deposit paid',money(totals().deposit))+line('Balance due '+dueDate(),money(totals().total-totals().deposit))+`<div class="mt">${detail('Guest signature',esc(state.quote.signature.name))}${detail('Reservation',state.reservation?`#00031 · ${badge(state.reservation.status)}`:'Awaiting venue review')}</div>`;footer=button('Close','close-modal')+button('View contract','doc-contract');guest=true;}
 else if(modal.startsWith('seed-')){const r=seedRows.find(x=>x[0]===modal.slice(5));title=r[0]+' · '+r[2];body=`<div class="grid2">${detail('Contact',r[1])}${detail('Group Type',r[3])}${detail('Dates',r[4])}${detail('Rooms',r[5])}${detail('Status',badge(r[7]))}${detail('Rate Range',r[6])}</div><p class="callout">Background record from the Figma list. The connected demo story follows Horizon Foundation · GBR-008.</p>`;footer=button('Close','close-modal');}
 else if(modal.startsWith('room-')){title='Reservation Room · RR-'+modal.slice(5).padStart(5,'0');body=detail('Group','GBR-008 · '+esc(state.request.group))+detail('Dates',dates())+detail('Status',badge(state.reservation.status))+detail('Room assignment',state.reservation.assigned?'Assigned to room '+(100+Number(modal.slice(5))):'Pending assignment');footer=button('Close','close-modal');size='small';}
 else{title='Booking Ninjas';body='<p>This section is outside the group booking demo. Use Reservations, Availability, Contacts or BN Invoices to continue the connected story.</p>';footer=button('Back to requests','request-list','primary');size='small';}
 $('#overlay').innerHTML=`<div class="modal-backdrop "><section class="modal ${size} ${guest?'guest-modal':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button><header class="modal-header">${title}</header><div class="modal-content">${body}</div><footer class="modal-footer">${footer}</footer></section></div>`;document.body.style.overflow='hidden';$('#overlay .modal-close')?.focus({preventScroll:true});}
function navigate(app,view){state.ui.app=app;state.ui[app]=view;save();render();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;handle(el.dataset.action,el);});
function captureWizard(){if(!wizard)return;const form=$('#wizard-form');if(!form)return;const v=Object.fromEntries(new FormData(form));if(wizard.step===2){wizard.layout=v.layout;wizard.spaceTime=v.spaceTime;wizard.spaceDays=Number(v.spaceDays);wizard.rooms.forEach((r,i)=>{r.qty=Number(v['room-'+i]);r.rate=Number(v['rate-'+i]);});}if(wizard.step===3){wizard.billedTo=v.billedTo.trim();wizard.tax=!!v.tax;}if(wizard.step===4){wizard.email=v.email.trim();wizard.sendEmail=!!v.sendEmail;}}
function validateRooms(){const q=wizard,r=state.request;requireState(q.rooms.every(x=>Number.isInteger(x.qty)&&x.qty>=0&&x.qty<=x.available&&x.rate>0&&x.rate<=2000),'Room counts must fit available inventory and rates must be positive.');requireState(q.rooms.filter(x=>x.bed==='Single').reduce((s,x)=>s+x.qty,0)===r.single&&q.rooms.filter(x=>x.bed==='Double').reduce((s,x)=>s+x.qty,0)===r.double,'Room selection must match the requested single and double beds.');requireState(Number.isInteger(q.spaceDays)&&q.spaceDays>0&&q.spaceDays<=nights(),'Meeting Hall days must fit the stay.');requireState(q.cateringQty>0,'Add group catering before continuing.');}
function openModal(next){lastFocus=document.activeElement;modal=next;renderOverlay();}
function handle(a,el){try{
 if(a==='switch-guest'||a==='switch-admin'){if(modal&&modal!=='reset'){toast('Finish or close the current dialog before switching apps.');return;}navigate(a==='switch-guest'?'guest':'admin',state.ui[a==='switch-guest'?'guest':'admin']);}
 else if(a==='guide'){state.ui.guide=!state.ui.guide;save();render();}
 else if(a==='recording'){state.ui.recording=!state.ui.recording;save();render();}
 else if(a==='reset')openModal('reset');
 else if(a==='confirm-reset'){state=initial();modal=null;wizard=null;resWizard=null;signatureMode='type';drawn=false;drawData=null;save();render();window.scrollTo(0,0);toast('Demo reset. The request form is empty and ready.');}
 else if(a==='close-modal'){modal=null;renderOverlay();lastFocus?.focus();}
 else if(a==='new-request'||a==='back-to-form'){if(state.quote){toast('Reset the demo to submit a new request after a quote has been sent.');return;}navigate('guest','form');}
 else if(a==='request-list'){modal=null;navigate('admin','list');}
 else if(a==='open-request'){modal=null;requireState(state.request,'Submit the guest request first.');navigate('admin','request');}
 else if(a==='open-block'){modal=null;requireState(state.quote,'Create and send the quote first.');navigate('admin','block');}
 else if(a==='open-reservation'){requireState(state.reservation,'Convert the group booking to reservation first.');navigate('admin','reservation');}
 else if(a==='reservation-show-availability'){modal=null;navigate('admin','availability');}
 else if(a==='availability-search'){captureAvailability();render();}
 else if(a==='availability-reset'){availability=null;render();}
 else if(a==='availability-sort'){availability.desc=!availability.desc;render();}
 else if(a==='availability-zoom-in'||a==='availability-zoom-out'){availability.zoom=Math.max(40,Math.min(96,availability.zoom+(a.endsWith('in')?8:-8)));render();}
 else if(a==='availability-new'){if(state.quote?.venueConfirmed&&!state.reservation)handle('start-reservation');else openModal('availability-help');}
 else if(a==='availability-booking'){if(state.reservation)navigate('admin','reservation');}
 else if(a==='availability')navigate('admin','availability');
 else if(a==='invoice'){requireState(state.reservation,'Create a reservation before viewing its invoice.');navigate('admin','invoice');}
 else if(a==='contact')navigate('admin','contacts');
 else if(a==='confirm-request'){transition(a);toast('Request confirmed. You can now create the group booking.');}
 else if(a==='start-wizard'){requireState(state.request?.status==='Confirmed'&&!state.quote,'Confirm the request before converting to a group block.');wizard=buildQuote();openModal('wizard');}
 else if(a==='wizard-back'){captureWizard();wizard.step--;renderOverlay();}
 else if(a==='wizard-next'){const form=$('#wizard-form');if(!form.reportValidity())return;captureWizard();if(wizard.step===2)validateRooms();if(wizard.step===3)requireState(!!wizard.billedTo,'Choose the person billed for the booking.');wizard.step++;renderOverlay();}
 else if(a==='send-quote'){if(!$('#wizard-form').reportValidity())return;captureWizard();validateRooms();transition(a);toast('Quote sent to '+state.quote.email+'. Switch to Guest App to open it.');}
 else if(a==='auto-rooms'){captureWizard();const s=state.request.single,d=state.request.double;wizard.rooms[0].qty=s;wizard.rooms[1].qty=Math.min(d,6);wizard.rooms[2].qty=d-wizard.rooms[1].qty;renderOverlay();toast('Requested rooms selected: '+(s+d)+' rooms.');}
 else if(a==='room-picker'||a==='addon-picker'){captureWizard();modal=a;renderOverlay();}
 else if(a==='picker-cancel'){modal='wizard';renderOverlay();}
 else if(a==='picker-apply'){wizard.rooms.forEach((x,i)=>{const val=Number($(`[name="pick-${i}"]`).value);requireState(Number.isInteger(val)&&val>=0&&val<=x.available,'Select quantities within available inventory.');});wizard.rooms.forEach((x,i)=>x.qty=Number($(`[name="pick-${i}"]`).value));modal='wizard';renderOverlay();}
 else if(a==='addon-apply'){const f=$('#addon-form');if(!f.reportValidity())return;wizard.cateringQty=Number(f.elements.cateringQty.value);wizard.cateringRate=Number(f.elements.cateringRate.value);modal='wizard';renderOverlay();}
 else if(a==='open-email'){requireState(state.quote,'Wait for the admin to send a quote.');navigate('guest','email');}
 else if(a==='view-received')navigate('guest','received');
 else if(a==='review-quote'){requireState(state.quote?.status==='Sent','The quote must be sent before review.');navigate('guest','review');}
 else if(a==='continue-sign'){requireState($('#review-checkbox')?.checked,'Review the quote, BEO and contract before signing.');navigate('guest','sign');}
 else if(a==='signature-type'||a==='signature-draw'){signatureMode=a==='signature-type'?'type':'draw';drawn=false;drawData=null;render();}
 else if(a==='clear-signature'){$('#signature-canvas').getContext('2d').clearRect(0,0,660,220);drawn=false;drawData=null;updateSignButton();}
 else if(a==='sign-contract'){transition(a);toast('Contract signed. Continue with the demo deposit.');}
 else if(a==='pay-deposit'){transition(a);toast('Demo deposit received: '+money(totals().deposit)+'. Admin can review the signed booking.');}
 else if(a==='my-booking'){navigate('guest',state.quote?.paid?'confirmed':state.quote?.signature?'payment':state.quote?'email':'received');}
 else if(a==='guest-booking-details')openModal('guest-booking');
 else if(a==='review-booking')openModal('review-booking');
 else if(a==='venue-confirm'){modal=null;transition(a);toast('Booking confirmed by the venue. Convert to reservation when ready.');}
 else if(a==='start-reservation'){requireState(state.quote?.venueConfirmed&&!state.reservation,'Review and confirm the signed booking first.');resWizard={step:1,color:'#fad659',notes:'Group reservation for GBR-008. Assign rooms after approval.'};openModal('reservation');}
 else if(a==='reservation-next'){const f=$('#reservation-form');resWizard.notes=f.elements.notes.value;resWizard.color=f.elements.color.value;resWizard.step=2;renderOverlay();}
 else if(a==='reservation-back'){resWizard.step=1;renderOverlay();}
 else if(a==='book-reservation'){transition(a);toast('Reservation #00031 created. Deposit carried to the invoice.');}
 else if(a==='approve-reservation'){transition(a);toast('Reservation #00031 confirmed. Guest booking updated.');}
 else if(a==='assign-rooms'){requireState(state.reservation?.status==='Confirmed','Confirm the reservation before assigning rooms.');openModal(a);}
 else if(a==='confirm-assign'){state.reservation.assigned=true;addEvent('All '+state.quote.rooms.reduce((s,x)=>s+x.qty,0)+' rooms assigned.','Sam Patel');modal=null;save();render();toast('Rooms assigned to reservation #00031.');}
 else if(a.startsWith('reservation-tab-')){state.ui.resTab=a.slice(16);save();render();}
 else if(a==='reservation-add-room'||a==='reservation-add-item'||a==='reservation-remove-item'){openModal('reservation-locked-services');}
 else if(a==='reservation-change-contact'){openModal('reservation-contact');}
 else if(a==='check-in'){state.reservation.checkedIn=true;addEvent('Reservation #00031 checked in.','Sam Patel');save();render();toast('Demo reservation checked in.');}
 else if(a==='check-out'){requireState(state.reservation.checkedIn,'Check in before checking out.');state.reservation.checkedOut=true;addEvent('Reservation #00031 checked out.','Sam Patel');save();render();toast('Demo reservation checked out.');}
 else if(a==='all-rooms'){state.ui.allRooms=!state.ui.allRooms;save();render();}
 else if(a.startsWith('doc-')){requireState(state.quote,'Send a quote before viewing its documents.');openModal(a);}
 else if(a.startsWith('download-')){requireState(state.quote,'Send a quote before downloading documents.');downloadPDF(a.slice(9));}
 else if(a==='calendar')downloadCalendar();
 else if(a==='scroll-notes')$('#notes')?.scrollIntoView({behavior:'smooth',block:'center'});
 else if(a==='add-note')openModal(a);
 else if(a==='save-note'){const f=$('#note-form');if(!f.reportValidity())return;addEvent(f.elements.note.value.trim(),'Sam Patel');modal=null;save();render();toast('Note added.');}
 else if(a==='assign-label'){requireState(state.request,'Submit the demo request before assigning its label.');openModal(a);}
 else if(a==='save-label'){const f=$('#label-form');if(!f.reportValidity())return;state.request.label=f.elements.label.value.trim();modal=null;save();render();toast('Label applied: '+state.request.label);}
 else if(a.startsWith('seed-')||a.startsWith('room-'))openModal(a);
 else if(a.startsWith('nav-')){const n=a.slice(4);if(n==='Reservations'||n==='Request-Manager')navigate('admin','list');else if(n==='Availability')navigate('admin','availability');else if(n==='Contacts')navigate('admin','contacts');else if(n==='BN-Invoices'){requireState(state.reservation,'An invoice appears after the demo reservation is created.');navigate('admin','invoice');}else openModal('outside-flow');}
 }catch(e){const box=$('#wizard-error')||$('#picker-error')||$('#signature-error')||$('#payment-error');if(box)box.textContent=e.message;else toast(e.message,true);}}
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='request-form'){try{submitRequest(e.target);}catch(error){const box=$('#request-error');box.hidden=false;box.textContent=error.message;}}});
document.addEventListener('input',e=>{const n=e.target.name;if(e.target.closest('#request-form')&&!state.request){state.draft=Object.fromEntries(new FormData(e.target.form));save();}if(n==='list-search'){const term=e.target.value.toLowerCase();$('#request-list').querySelectorAll('tbody tr').forEach(tr=>tr.hidden=!tr.dataset.search.includes(term));}if(n==='fullname'){if($('#signature-preview'))$('#signature-preview').textContent=e.target.value;updateSignButton();}});
document.addEventListener('change',e=>{if(e.target.closest('#request-form')&&!state.request){state.draft=Object.fromEntries(new FormData(e.target.form));save();}if(e.target.name==='availability-zoom'){availability.zoom=Number(e.target.value);$('#availability-grid').style.setProperty('--day-width',availability.zoom+'px');}if(e.target.id==='review-checkbox')$('[data-action="continue-sign"]').disabled=!e.target.checked;if(e.target.id==='signature-agree')updateSignButton();});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){handle('close-modal');return;}if(e.key==='Tab'){const focusable=[...$('#overlay').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(x=>x.offsetParent!==null);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
function updateSignButton(){const f=$('#signature-form');if(!f)return;const valid=f.elements.fullname.value.trim()&&f.elements.agree.checked&&(signatureMode==='type'||drawn);$('[data-action="sign-contract"]').disabled=!valid;}
function bindCanvas(){const canvas=$('#signature-canvas');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.lineWidth=3;ctx.strokeStyle='#0b1f17';ctx.lineCap='round';let drawing=false;const point=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];};canvas.addEventListener('pointerdown',e=>{drawing=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));});canvas.addEventListener('pointermove',e=>{if(!drawing)return;ctx.lineTo(...point(e));ctx.stroke();drawn=true;});const end=()=>{drawing=false;if(drawn)drawData=canvas.toDataURL('image/png');updateSignButton();};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);}
function downloadBlob(content,type,filename){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.hidden=true;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast(filename+' download prepared.');}
function downloadCalendar(){const r=state.request;const clean=x=>x.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Cedar Valley//Retreat Demo//EN','BEGIN:VEVENT','UID:GBR-008@cedarvalley.example','DTSTAMP:20260922T120000Z','DTSTART;VALUE=DATE:'+r.start.replaceAll('-',''),'DTEND;VALUE=DATE:'+r.end.replaceAll('-',''),'SUMMARY:'+clean(r.group),'LOCATION:Cedar Valley Retreat & Conference Center','DESCRIPTION:Group code GBR-008. '+(r.single+r.double)+' rooms.','END:VEVENT','END:VCALENDAR'].join('\r\n');downloadBlob(text,'text/calendar','Cedar_Valley_GBR-008.ics');}
function pdfText(type){const r=state.request,q=state.quote,t=totals();const title=type==='beo'?'Banquet Event Order':type==='invoice'?'Invoice INV-00031':'Group Booking Contract';const result=['CEDAR VALLEY RETREAT & CONFERENCE CENTER',title+' - GBR-008','',r.group,'Organizer: '+name()+' - '+r.organization,'Dates: '+dates()+' ('+nights()+' nights)','Rooms: '+(r.single+r.double)+' - '+r.single+' single bed, '+r.double+' double bed','Email: '+q.email,''];if(type==='contract')result.push('1. Event',r.group+' with '+(r.single+r.double)+' rooms, Meeting Hall for '+q.spaceDays+' days,','and group catering for '+r.guests+' guests.','','2. Payment','50% deposit '+money(t.deposit)+' due on signing.','Remaining balance '+money(t.total-t.deposit)+' due '+dueDate()+'.','','3. Changes and cancellation','Room counts can be adjusted until Oct 30, 2026.','Cancellations are charged according to the venue policy.','','4. Billing','Rooms and add-ons are billed to the organizer on one invoice.');else{result.push('DESCRIPTION                         QTY       RATE        TOTAL');quoteRows().forEach(x=>result.push(x[0]+' | '+x[1]+' | '+x[3]+' | '+x[4]));result.push('','Subtotal: '+money(t.subtotal),'Taxes: '+money(t.tax),'Grand Total: '+money(t.total),'Deposit: '+money(t.deposit),'Balance: '+money(t.total-t.deposit)+' due '+dueDate());if(type==='beo')result.push('','Agenda:','Arrival and Check-in - 3:00 PM to 5:00 PM - Main Lodge Lobby','Leadership Sessions - '+q.spaceTime+' - Meeting Hall','Group Dinner - 6:30 PM to 8:30 PM - Dining Hall');}result.push('','Client signature: '+(q.signature?.name||'Awaiting signature'),q.signature?'Signed electronically - Sep 22, 2026':'','Venue signature: '+(q.venueConfirmed?'Jordan Reyes - Sep 22, 2026':'Awaiting venue confirmation'),'','Interactive demo document. Payment simulated; no charge made.');return result;}
function downloadPDF(type){const ascii=s=>s.replace(/[–—]/g,'-').replace(/[^\x20-\x7e]/g,'').replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');const lines=pdfText(type).flatMap(s=>{const out=[];let rest=s;while(rest.length>90){let pos=rest.lastIndexOf(' ',90);if(pos<1)pos=90;out.push(rest.slice(0,pos));rest=rest.slice(pos).trim();}out.push(rest);return out;});const stream='BT /F1 10 Tf 14 TL 45 790 Td '+lines.map((s,i)=>(i?'T* ':'')+'('+ascii(s)+') Tj').join('\n')+' ET';const objs=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length '+stream.length+' >>\nstream\n'+stream+'\nendstream'];let out='%PDF-1.4\n',offsets=[0];objs.forEach((o,i)=>{offsets.push(out.length);out+=(i+1)+' 0 obj\n'+o+'\nendobj\n';});const xref=out.length;out+='xref\n0 6\n0000000000 65535 f \n'+offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';downloadBlob(out,'application/pdf',(type==='beo'?'BEO':type==='invoice'?'Invoice':'Contract')+'_GBR-008.pdf');}
window.addEventListener('storage',e=>{if(e.key!==STORE)return;try{const other=JSON.parse(e.newValue);if(other?.version===1){const ui=state.ui;state=other;state.ui=ui;modal=null;render();toast('Booking data updated from another demo tab.');}}catch{}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_booking_state',description:'Read the current connected demo request, quote and reservation.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({request:state.request,quote:state.quote,reservation:state.reservation,totals:totals()})},{name:'navigate_demo_app',description:'Switch to guest or admin without changing booking status.',inputSchema:{type:'object',properties:{app:{type:'string',enum:['guest','admin']}},required:['app'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{requireState(input&&['guest','admin'].includes(input.app),'app must be guest or admin');navigate(input.app,state.ui[input.app]);return {app:state.ui.app,view:state.ui[input.app]};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
render();


